    out = [row[:] for row in grid]

    # Locate the solid 2 divider.
    divider = None
    for r in range(h):
        if all(v == 2 for v in grid[r]):
            divider = ("row", r)
            break
    if divider is None:
        for c in range(w):
            if all(grid[r][c] == 2 for r in range(h)):
                divider = ("col", c)
                break
    if divider is None:
        return out

    orient, d = divider
    counts = [0] * 10
    for row in grid:
        for v in row:
            if v != 2:
                counts[v] += 1
    background = max(range(10), key=lambda v: counts[v])

    cells = [(r, c, grid[r][c])
             for r in range(h) for c in range(w)
             if grid[r][c] not in (background, 2)]
    if not cells:
        return out

    if orient == "row":
        lo = min(r for r, c, v in cells)
        hi = max(r for r, c, v in cells)
        if hi < d:  # object above divider
            shift = d - 1 - hi
            line = lo + shift - 1
        else:       # object below divider
            shift = d + 1 - lo
            line = hi + shift + 1
        for r, c, v in cells:
            out[r][c] = background
        for r, c, v in cells:
            out[r + shift][c] = v
        if 0 <= line < h:
            out[line] = [8] * w
    else:
        lo = min(c for r, c, v in cells)
        hi = max(c for r, c, v in cells)
        if hi < d:  # object left of divider
            shift = d - 1 - hi
            line = lo + shift - 1
        else:       # object right of divider
            shift = d + 1 - lo
            line = hi + shift + 1
        for r, c, v in cells:
            out[r][c] = background
        for r, c, v in cells:
            out[r][c + shift] = v
        if 0 <= line < w:
            for r in range(h):
